mapper.insert:

  SELECT INSPECTIONS_SEQ.NEXTVAL FROM dual

INSERT INTO inspections (
  inspection_id, submitted_at, result, facility_id, inspector_id
) VALUES (
  #{inspectionId},
  #{submittedAt, jdbcType=TIMESTAMP},
  #{result},
  #{facilityId},
  #{inspectorId}
)

mapper.select:
SELECT type
